 internal void RefreshAccounts(){if(connectionIntro!=null)connectionIntro.Text=accounts.Count>0?"Acesso somente de leitura":"Conecte sua conta para ver eventos. Acesso somente de leitura.";accountPanel.Children.Clear();accountPage=Math.Clamp(accountPage,0,Math.Max(0,accounts.Count-1));foreach(var a in accounts.Skip(accountPage).Take(1)){var row=new DockPanel();var remove=IconButton("\uE711","Desconectar "+a.Email,()=>{accounts.Remove(a);main.AccountsChanged();RefreshAccounts();RefreshCalendars();});DockPanel.SetDock(remove,Dock.Right);row.Children.Add(remove);var caption=new StackPanel();var name=MainWindow.Label(a.Email,12,true);name.TextWrapping=TextWrapping.NoWrap;name.TextTrimming=TextTrimming.CharacterEllipsis;name.ToolTip=a.Email;caption.Children.Add(name);caption.Children.Add(MainWindow.Label(a.Provider=="Google"?"Google":a.Provider=="LocalIcs"?"Arquivo iCalendar":"Assinatura iCalendar",12));row.Children.Add(caption);accountPanel.Children.Add(new Border{CornerRadius=new CornerRadius(8),Padding=new Thickness(8),Margin=new Thickness(0,4,0,4),Background=new SolidColorBrush(Color.FromArgb(18,128,128,128)),Child=row});}if(accounts.Count>1)accountPanel.Children.Add(Pager(accountPage,accounts.Count,p=>{accountPage=p;RefreshAccounts();}));if(accounts.Count==0)accountPanel.Children.Add(MainWindow.Label("Nenhuma conta conectada",12));}
