 void RefreshCalendars(){var available=main.snapshots.Values.SelectMany(s=>s.Calendars).GroupBy(c=>c.Id).Select(g=>g.First()).ToList();var signature=accounts.Count+"|"+string.Join("|",available.Select(c=>c.Id+":"+c.Name))+"|"+string.Join("|",settings.HiddenCalendars);if(signature==calendarSignature)return;calendarSignature=signature;calendarPanel.Children.Clear();if(available.Count==0)calendarPanel.Children.Add(MainWindow.Label(accounts.Count==0?"Conecte um calendário para escolher as agendas":"Aguardando atualização",12));calendarPage=Math.Clamp(calendarPage,0,Math.Max(0,(available.Count-1)/3));foreach(var c in available.Skip(calendarPage*3).Take(3)){var check=Check("\uE787",c.Name,!settings.HiddenCalendars.Contains(c.Id));check.MaxHeight=42;check.ToolTip=c.Name;check.Click+=(_,_)=>{settings.HiddenCalendars.Remove(c.Id);if(check.IsChecked!=true)settings.HiddenCalendars.Add(c.Id);main.Persist();main.Render();};calendarPanel.Children.Add(check);}if(available.Count>3)calendarPanel.Children.Add(Pager(calendarPage,(available.Count+2)/3,p=>{calendarPage=p;calendarSignature="";RefreshCalendars();}));}
